else
  pin_clone "asadullah48/hackathon-skills-marketplace" "$MS_DIR" "$MARKETPLACE_PIN"
fi
for s in systematic-debugging dispatching-parallel-agents brainstorming agents-md-generator verification-before-completion; do
  src=""
