}
mkdir -p "$SKILL_SRC"
fetch_repo "peterbamuhigire/chwezi-dev-engine" "chwezi-dev-engine" "$CHWEZI_PIN"
fetch_repo "andomo3/flecto-shade" "flecto-shade" "$FLECTO_PIN"
