import os, sys
base = sys.argv[1]
_files = set()
_replacements = [0]

def audit6_patch(path, subs):
    _files.add(path)
    text = open(path, encoding="utf-8").read()
    for old, new in subs:
        assert text.count(old) == 1, f"{path}: pattern not found exactly once: {old[:70]!r}"
        text = text.replace(old, new)
        _replacements[0] += 1
    open(path, "w", encoding="utf-8").write(text)

