        # pattern.
        _is_dashboard = (
            "dashboard" in (category or "").casefold()
            or (reasoning.get("is_default")
                and "dashboard" in (query or "").casefold())
            or "dashboard" in (reasoning.get("pattern", "") or "").casefold()
        )
        if _is_dashboard and not _landing_matched:'''),
])

